73	    /**
74	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
75	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
81	     * after the {@code @}, compared case-insensitively) is listed here is rejected with a 400.
82	     */
83	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
84	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
